mapper.sql:
EXISTS (SELECT 1 FROM ( SELECT 'PUR_REQUEST' AS kind, r.request_seq AS seq, pl.org_seq, r.created_by AS owner FROM tb_purchase_request r LEFT JOIN tb_plant pl ON pl.plant_seq = r.plant_seq UNION ALL SELECT 'PUR_ORDER', o.order_seq, pl.org_seq, o.created_by FROM tb_purchase_order o LEFT JOIN tb_plant pl ON pl.plant_seq = o.plant_seq UNION ALL SELECT 'INBOUND', i.inbound_seq, pl.org_seq, i.created_by FROM tb_inbound i LEFT JOIN tb_plant pl ON pl.plant_seq = i.plant_seq UNION ALL SELECT 'OUTBOUND', o.outbound_seq, pl.org_seq, o.instructed_by FROM tb_outbound o LEFT JOIN tb_plant pl ON pl.plant_seq = o.plant_seq UNION ALL SELECT 'WAYBILL', w.waybill_seq, pl.org_seq, w.issued_by FROM tb_waybill w JOIN tb_pack_box b ON b.box_seq = w.box_seq JOIN tb_outbound o ON o.outbound_seq = b.outbound_seq LEFT JOIN tb_plant pl ON pl.plant_seq = o.plant_seq UNION ALL SELECT 'ORDER', o.order_seq, pl.org_seq, o.created_by FROM tb_order o JOIN tb_order_line ol ON ol.order_seq = o.order_seq LEFT JOIN tb_stock_alloc a ON a.order_line_seq = ol.line_seq LEFT JOIN tb_stock s ON s.stock_seq = a.stock_seq LEFT JOIN tb_location l ON l.location_seq = s.location_seq LEFT JOIN tb_warehouse wh ON wh.warehouse_seq = l.warehouse_seq LEFT JOIN tb_plant pl ON pl.plant_seq = wh.plant_seq UNION ALL SELECT 'SKU', k.sku_seq, NULL::bigint, k.created_by FROM tb_sku k UNION ALL SELECT 'INBOUND_CORRECT', c.correct_seq, pl.org_seq, c.requested_by FROM tb_inbound_correct c JOIN tb_inbound i ON i.inbound_seq = c.inbound_seq JOIN tb_plant pl ON pl.plant_seq = i.plant_seq UNION ALL SELECT 'ADJUST', a.adjust_seq, pl.org_seq, a.requested_by FROM tb_stock_adjust a JOIN tb_warehouse wh ON wh.warehouse_seq = a.warehouse_seq JOIN tb_plant pl ON pl.plant_seq = wh.plant_seq UNION ALL SELECT 'STOCKTAKE', t.take_seq, pl.org_seq, t.created_by FROM tb_stocktake t JOIN tb_warehouse wh ON wh.warehouse_seq = t.warehouse_seq JOIN tb_plant pl ON pl.plant_seq = wh.plant_seq UNION ALL SELECT h.ref_type, h.history_seq, pl.org_seq, s.created_by FROM tb_stock_history h JOIN tb_stock s ON s.stock_seq = h.stock_seq JOIN tb_location l ON l.location_seq = s.location_seq JOIN tb_warehouse wh ON wh.warehouse_seq = l.warehouse_seq JOIN tb_plant pl ON pl.plant_seq = wh.plant_seq WHERE h.ref_type IN ('MOVE', 'UNSELLABLE') ) access WHERE access.kind = ${documentKind} AND access.seq = ${documentSeq}
AND (access.kind = 'SKU' OR access.owner = #{scope.ownerId}
OR access.org_seq IN #{org} ) )
